// 일반기업회계기준 (K-GAAP) 전 35개 장(개념체계, 제1장~제33장, 시행일 및 경과규정) 원문 및 부록(결론도출근거·실무지침·적용사례) 전체 데이터
// 출처: 한국회계기준원(KASB) 회계기준위원회 의결 일반기업회계기준 정본 (제정 2009.11.27. ~ 최종개정 2023.12.26.)

export interface GeneralStandardArticle {
    id: string;
    chapterNo: string;        // 예: "개념체계", "제1장", ..., "제24장", ..., "제30장", ..., "제33장", "부칙·경과"
    chapterTitle: string;     // 예: "보고기간후사건"
    articleNo: string;        // 예: "문단 24.1 ~ 24.4", "제24장 용어의 정의"
    articleTitle: string;     // 예: "목적 · 보고기간후사건 · 수정을 요하는 보고기간후사건"
    paragraphs: string[];     // 기준서 본문 원문 문단 배열 (100% 무누락 원문)
    relatedGuidanceIds: string[]; // 우측 부록(결론도출근거·실무지침·적용사례) 연결 ID 배열
    keywords: string[];       // 검색 키워드 태그
    pdfUrl: string;           // 장별 공식 PDF 원문 경로
}

export interface GeneralGuidanceSection {
    id: string;
    chapterNo: string;        // 예: "제24장", "제30장", "제31장"
    sectionNo: string;        // 예: "제24장 결론도출근거 (결24.1~결24.4)", "제30장 적용사례"
    sectionTitle: string;     // 예: "보고기간후사건 부록 — 결론도출근거 원문"
    summaryTable?: {
        title: string;
        rows: string[];
    };
    blocks: {
        subtitle: string;
        content: string[];
        exampleBox?: {
            title: string;
            lines: string[];
        };
    }[];
    relatedArticleIds: string[]; // 좌측 기준서 본문 연결 ID 배열
    keywords: string[];
    pdfUrl: string;
}

